mapper.select:
SELECT f.*, (SELECT COUNT(*) FROM AI_VEC_FOLDER cf WHERE cf.PARENT_ID = f.ID AND cf.DELETED = 0) AS childCount, (SELECT COUNT(*) FROM AI_VEC_DOC d WHERE d.FOLDER_ID = f.ID AND d.DELETED = 0) AS docCount FROM AI_VEC_FOLDER f WHERE f.DELETED = 0
AND f.COLLECTION_ID = #{req.collectionId}
AND f.PARENT_ID = #{req.parentId}
AND f.PARENT_ID IS NULL
ORDER BY f.SORT_ORDER ASC, f.CREATE_TIME DESC
